export const DEFAULT_CONFIG = Object.freeze({
    instrumentHttp: true,
    instrumentFetch: true,
    instrumentReact: true,
    captureErrors: true,
});
export function mergeConfig(config = {}) {
    if (config === null || typeof config !== "object" || Array.isArray(config)) {
        throw new TypeError("Auto-instrumentation config must be an object");
    }
    const raw = config;
    const merged = {};
    for (const key of [
        "instrumentHttp",
        "instrumentFetch",
        "instrumentReact",
        "captureErrors",
    ]) {
        const value = raw[key] === undefined ? DEFAULT_CONFIG[key] : raw[key];
        if (typeof value !== "boolean") {
            throw new TypeError(`Auto-instrumentation ${key} must be a boolean`);
        }
        merged[key] = value;
    }
    if (raw.tracing !== undefined) {
        merged.tracing = snapshotNestedConfig(raw.tracing, "tracing");
    }
    if (raw.metrics !== undefined) {
        merged.metrics = snapshotNestedConfig(raw.metrics, "metrics");
    }
    return merged;
}
function snapshotNestedConfig(value, name) {
    if (value === null || typeof value !== "object" || Array.isArray(value)) {
        throw new TypeError(`Auto-instrumentation ${name} config must be an object`);
    }
    const snapshot = { ...value };
    if (typeof snapshot.enabled !== "boolean") {
        throw new TypeError(`Auto-instrumentation ${name} enabled must be a boolean`);
    }
    return snapshot;
}
